from typing import Any, Dict, Iterable, List, Optional, Text

import structlog

from rasa.core.brokers.broker import EventBroker
from rasa.core.secrets_manager.secret_manager import EndpointResolver
from rasa.core.tracker_stores.tracker_store import TrackerStore, create_tracker_store
from rasa.shared.core.domain import Domain
from rasa.shared.core.trackers import DialogueStateTracker
from rasa.utils.endpoints import EndpointConfig

structlogger = structlog.get_logger(__name__)

DEFAULT_RETRIES = 3


class AuthRetryTrackerStore(TrackerStore):
    """Tracker store wrapper which implements retry mechanism in every abstract method.

    The retry mechanism first updates credentials from the secret manager.
    """

    def __init__(
        self,
        domain: "Domain",
        endpoint_config: "EndpointConfig",
        retries: int = DEFAULT_RETRIES,
        event_broker: Optional["EventBroker"] = None,
    ) -> None:
        """Initialise the tracker store wrapper."""
        self.retries = self.validate_retries(retries)
        self.endpoint_config = endpoint_config

        self._tracker_store = self.recreate_tracker_store(domain, event_broker)

        super().__init__(domain, event_broker)

    @property
    def domain(self) -> Domain:
        """Returns the domain of the wrapped tracker store."""
        return self._tracker_store.domain

    @domain.setter
    def domain(self, domain: Optional[Domain]) -> None:
        """Sets the domain of wrapped tracker store."""
        self._tracker_store.domain = domain or Domain.empty()

    @staticmethod
    def validate_retries(retries: int) -> int:
        """Validate the number of retries."""
        if retries <= 0:
            structlogger.warning(
                "auth_retry_tracker_store.validate_retries.invalid",
                event_info=(
                    "Invalid number of retries. Using default number of retries."
                ),
                retries=retries,
                default_retries=DEFAULT_RETRIES,
            )
            return DEFAULT_RETRIES
        else:
            return retries

    async def keys(self) -> Iterable[Text]:
        """Retries retrieving the keys if it fails."""
        # add + 1 to retries because the retries are additional to the first attempt
        for _ in range(self.retries + 1):
            try:
                return await self._tracker_store.keys()
            except Exception as e:
                structlogger.warning(
                    "auth_retry_tracker_store.keys.failed_retrying",
                    event_info="Failed to retrieve keys. Retrying.",
                    error=str(e),
                )
                self._tracker_store = self.recreate_tracker_store(
                    self.domain, self.event_broker
                )
        else:
            structlogger.error(
                "auth_retry_tracker_store.keys.failed_exhausted",
                event_info="Failed to retrieve keys after all retries.",
                retries=self.retries,
            )
            return []

    async def retrieve(self, sender_id: Text) -> Optional["DialogueStateTracker"]:
        """Retries retrieving the tracker if it fails."""
        # add + 1 to retries because the retries are additional to the first attempt
        for _ in range(self.retries + 1):
            try:
                return await self._tracker_store.retrieve(sender_id)
            except Exception as e:
                structlogger.warning(
                    "auth_retry_tracker_store.retrieve.failed_retrying",
                    event_info="Failed to retrieve tracker. Retrying.",
                    sender_id=sender_id,
                    error=str(e),
                )
                self._tracker_store = self.recreate_tracker_store(
                    self.domain, self.event_broker
                )
        else:
            structlogger.error(
                "auth_retry_tracker_store.retrieve.failed_exhausted",
                event_info="Failed to retrieve tracker after all retries.",
                sender_id=sender_id,
                retries=self.retries,
            )
            return None

    async def retrieve_full_tracker(
        self, sender_id: Text
    ) -> Optional["DialogueStateTracker"]:
        """Retries retrieving the full tracker if it fails."""
        # add + 1 to retries because the retries are additional to the first attempt
        for _ in range(self.retries + 1):
            try:
                return await self._tracker_store.retrieve_full_tracker(sender_id)
            except Exception as e:
                structlogger.warning(
                    "auth_retry_tracker_store.retrieve_full_tracker.failed_retrying",
                    event_info="Failed to retrieve full tracker. Retrying.",
                    sender_id=sender_id,
                    error=str(e),
                )
                self._tracker_store = self.recreate_tracker_store(
                    self.domain, self.event_broker
                )

        structlogger.error(
            "auth_retry_tracker_store.retrieve_full_tracker.failed_exhausted",
            event_info="Failed to retrieve full tracker after all retries.",
            sender_id=sender_id,
            retries=self.retries,
        )
        return None

    async def save(self, tracker: "DialogueStateTracker") -> None:
        """Retries saving the tracker if it fails."""
        # add + 1 to retries because the retries are additional to the first attempt
        for _ in range(self.retries + 1):
            try:
                await self._tracker_store.save(tracker)
                break
            except Exception as e:
                structlogger.warning(
                    "auth_retry_tracker_store.save.failed_retrying",
                    event_info="Failed to save tracker. Retrying.",
                    sender_id=tracker.sender_id,
                    error=str(e),
                )
                self._tracker_store = self.recreate_tracker_store(
                    self.domain, self.event_broker
                )
        else:
            structlogger.error(
                "auth_retry_tracker_store.save.failed_exhausted",
                event_info="Failed to save tracker after all retries.",
                sender_id=tracker.sender_id,
                retries=self.retries,
            )

    def recreate_tracker_store(
        self, domain: "Domain", event_broker: Optional["EventBroker"] = None
    ) -> TrackerStore:
        """Recreate tracker store with updated credentials."""
        endpoint_config = EndpointResolver.update_config(self.endpoint_config)
        return create_tracker_store(endpoint_config, domain, event_broker)

    async def delete(self, sender_id: str) -> None:
        """Retries deleting the tracker for the given sender_id."""
        # add + 1 to retries because the retries are additional to the first attempt
        for _ in range(self.retries + 1):
            try:
                await self._tracker_store.delete(sender_id)
                break
            except Exception as e:
                structlogger.warning(
                    "auth_retry_tracker_store.delete.failed_retrying",
                    event_info="Failed to delete tracker. Retrying.",
                    sender_id=sender_id,
                    error=str(e),
                )
                self._tracker_store = self.recreate_tracker_store(
                    self.domain, self.event_broker
                )
        else:
            structlogger.error(
                "auth_retry_tracker_store.delete.failed_exhausted",
                event_info="Failed to delete tracker after all retries.",
                sender_id=sender_id,
                retries=self.retries,
            )

    async def update(
        self, tracker: DialogueStateTracker, apply_deletion_only: bool = True
    ) -> None:
        """Retries replacing the tracker if it fails."""
        # add + 1 to retries because the retries are additional to the first attempt
        for _ in range(self.retries + 1):
            try:
                await self._tracker_store.update(
                    tracker, apply_deletion_only=apply_deletion_only
                )
                break
            except Exception as e:
                structlogger.warning(
                    "auth_retry_tracker_store.update.failed_retrying",
                    event_info="Failed to replace tracker. Retrying.",
                    sender_id=tracker.sender_id,
                    error=str(e),
                )
                self._tracker_store = self.recreate_tracker_store(
                    self.domain, self.event_broker
                )
        else:
            structlogger.error(
                "auth_retry_tracker_store.update.failed_exhausted",
                event_info="Failed to replace tracker after all retries.",
                sender_id=tracker.sender_id,
                retries=self.retries,
            )

    async def get_trackers_by_user_id(
        self,
        user_id: str,
        limit: Optional[int] = None,
        skip: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        """Retries retrieving trackers by user_id if it fails."""
        # add + 1 to retries because the retries are additional to the first attempt
        for _ in range(self.retries + 1):
            try:
                return await self._tracker_store.get_trackers_by_user_id(
                    user_id, limit=limit, skip=skip
                )
            except Exception as e:
                structlogger.warning(
                    "auth_retry_tracker_store.get_trackers_by_user_id.failed_retrying",
                    event_info="Failed to retrieve trackers by user_id. Retrying.",
                    user_id=user_id,
                    error=str(e),
                )
                self._tracker_store = self.recreate_tracker_store(
                    self.domain, self.event_broker
                )

        structlogger.error(
            "auth_retry_tracker_store.get_trackers_by_user_id.failed_exhausted",
            event_info="Failed to retrieve trackers by user_id after all retries.",
            user_id=user_id,
            retries=self.retries,
        )
        return []

    async def get_serialized_trackers_by_user_id(
        self,
        user_id: str,
        limit: Optional[int] = None,
        skip: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        """Retries retrieving serialized trackers by user_id if it fails.

        Args:
            user_id: User ID to fetch trackers for.
            limit: Optional maximum number of trackers to return.
            skip: Optional number of trackers to skip.

        Returns:
            List of serialized tracker dicts, or empty list after exhausting retries.
        """
        for _ in range(self.retries + 1):
            try:
                return await self._tracker_store.get_serialized_trackers_by_user_id(
                    user_id, limit=limit, skip=skip
                )
            except Exception as e:
                structlogger.warning(
                    "auth_retry_tracker_store"
                    ".get_serialized_trackers_by_user_id.failed_retrying",
                    event_info=(
                        "Failed to retrieve serialized trackers by user_id. Retrying."
                    ),
                    user_id=user_id,
                    error=str(e),
                )
                self._tracker_store = self.recreate_tracker_store(
                    self.domain, self.event_broker
                )

        structlogger.error(
            "auth_retry_tracker_store"
            ".get_serialized_trackers_by_user_id.failed_exhausted",
            event_info=(
                "Failed to retrieve serialized trackers by user_id after all retries."
            ),
            user_id=user_id,
            retries=self.retries,
        )
        return []
